        end
    end
    assign bit_count = pop_count;

    // Output sum module
    reg [7:0] sum;
    always @(posedge clk, posedge reset) begin
        if (reset) begin
            sum <= 8'b0;
        end else begin
            sum <= edge_detect + pop_count;
        end
    end
    assign output_sum = sum;

endmodule

