description:
Design a combined multiplication and division module that processes two 32-bit signed inputs, `a` and `b`, based on a 3-bit mode selector. The module outputs a 32-bit result `q`, which can represent various operations: multiplication of `a` and `b`, both signed and unsigned, returning either the lower or upper bits of the product, or performing division and modulus operations, again for both signed and unsigned scenarios. The specific operation is determined by the value of `mode`, with each combination directing the output to the appropriate arithmetic operation result.
module top_module(
    input wire [31:0] a, b,
    output reg [31:0] q,
    input wire [2:0] mode
);

code:
module top_module(
    input wire [31:0] a, b,
    output reg [31:0] q,
    input wire [2:0] mode
);reg [63:0] fullq;

    always @(*) begin
        case (mode)
            3'b000: begin
                fullq = $signed(a) * $signed(b);
                q = fullq[31:0];
            end 
            3'b001: begin
                fullq = $signed(a) * $signed(b);
                q = fullq[63:32];
            end
            3'b010: begin
                fullq = $signed(a) * $signed({1'b0, b});
                q = fullq[63:32];
            end
            3'b011: begin
                fullq = a * b;
                q = fullq[63:32];
            end
            3'b100: begin
                q <= $signed(a) / $signed(b);
            end
            3'b101: begin
                q <= a / b;
            end
            3'b110: begin 
                q <= $signed(a) % $signed(b);
            end
            3'b111: begin
                q <= a % b;
            end
        endcase
    end

endmodule

