description:
Design a control system for managing a backlight based on touch input and a timer. The module has two states: 'DISPLAY_ON' and 'DISPLAY_OFF.' When a touch event occurs, it transitions to 'DISPLAY_ON,' which triggers the backlight (output o_Light = HIGH). The backlight remains active until a specified time passes (indicated by the overflow of a 34-bit counter). Once the counter's high bit is reached, it moves to 'DISPLAY_OFF,' turning off the light output. The counter resets on touch, allowing the backlight to stay on longer with continued interaction.
module top_module(
    input i_Clk,
    input i_Touch,
    output o_Light
);

code:
module top_module(
    input i_Clk,
    input i_Touch,
    output o_Light
);localparam STATE_DISPLAY_OFF = 1'd0;
localparam STATE_DISPLAY_ON  = 1'd1;

reg [33:0] r_Counter = 34'd0;
reg r_CurrentState = STATE_DISPLAY_ON;
reg r_NextState;


always @(posedge i_Clk) begin
    r_CurrentState <= r_NextState;
end

always @(*) begin
    r_NextState = r_CurrentState;
    case (r_CurrentState)
        STATE_DISPLAY_OFF: begin
            if (i_Touch)
                r_NextState = STATE_DISPLAY_ON;
        end
        STATE_DISPLAY_ON: begin
            if (r_Counter[33])
                r_NextState = STATE_DISPLAY_OFF;
        end
    endcase
end


always @(posedge i_Clk) begin
    if (i_Touch)
        r_Counter <= 34'd0;
    else
        r_Counter <= r_Counter + 1'd1;
end


assign o_Light = (r_CurrentState == STATE_DISPLAY_ON);

endmodule

