description:
Design a 4-bit binary adder that computes the sum of two 4-bit inputs, A and B. The module outputs a 5-bit result, C, which includes the sum and a carry-out indicator in the most significant bit. The carry-out is determined by detecting overflow conditions when both inputs are positive or when an overflow occurs in the addition of the two values.
module top_module(
    A,
    B,
    C
);

code:
module top_module(
    A,
    B,
    C
);input [3:0] A;
    input [3:0] B;
    output [4:0] C;

    wire [3:0] sum;
    wire overflow;

    assign sum = A + B;

    assign overflow = ((A[3] & B[3]) | (A[3] & ~sum[3]) | (B[3] & ~sum[3]));

    assign C = {overflow, sum};

endmodule

