description:
Design a 16-bit to 32-bit sign and zero extension module. The module takes a 16-bit immediate value (`imm`) and a 2-bit operation code (`EOp`) to determine how to extend the value. Depending on the value of `EOp`, the immediate is conditionally concatenated with either zero-filled or sign-extended bits to produce a 32-bit output. Specifically, `EOp` dictates whether to sign-extend (EOp=00 or 11) or zero-extend (EOp=01 or 10), and for EOp=11, the resulting output is also left-shifted by two bits.
module top_module(
    input [15:0] imm,
    input [1:0] EOp,
    output reg [31:0] ext
    );

code:
module top_module(
    input [15:0] imm,
    input [1:0] EOp,
    output reg [31:0] ext
    );reg [15:0] a;
integer i;
always @(*)
begin
	case(EOp)
	2'b00:
	begin
		if(imm[15]==0)
		begin
			for(i=0;i<16;i=i+1)a[i]=0;
		end
		if(imm[15]==1)
		begin
			for(i=0;i<16;i=i+1)a[i]=1;
		end
		ext={a,imm};
	end
	2'b01:
	begin
		for(i=0;i<16;i=i+1)a[i]=0;
		ext={a,imm};
	end
	2'b10:
	begin
		for(i=0;i<16;i=i+1)a[i]=0;
		ext={imm,a};
	end
	2'b11:
	begin
		if(imm[15]==0)
		begin
			for(i=0;i<16;i=i+1)a[i]=0;
		end
		if(imm[15]==1)
		begin
			for(i=0;i<16;i=i+1)a[i]=1;
		end
		ext={a,imm};
		ext=ext<<2;
	end
	endcase
end

endmodule

