module top_module(d, g, p, a, b, c, S);output d, g, p;
  input a, b, c;
  input [2:0] S;
  reg g,p,d,cint,bint;

  always @(a,b,c,S,p,g) begin 
    bint = S[0] ^ b;
    g = a & bint;
    p = a ^ bint;
    cint = S[1] & c;

  if(S[2]==0)
    begin
      d = p ^ cint;
    end

  else if(S[2]==1)
    begin
      if((S[1]==0) & (S[0]==0)) begin
        d = a | b;
      end
      else if ((S[1]==0) & (S[0]==1)) begin
        d = ~(a|b);
      end
      else if ((S[1]==1) & (S[0]==0)) begin
        d = a&b;
      end
      else
        d = 1;
      end
    end
endmodule

